  # CheckoutCreated is a resource of Peráta's API.
  class CheckoutCreated < Model
    MEMBERS = %i[amount_cents cancel_url client_reference_id client_secret client_secret_expires_at created_at discount_id expires_at first_period_extra_days id items label metadata notify_customer_email price_id product_id quantity renewal_mode session_id showcase_id status status_key subscription_start_at success_url url].freeze

    # O valor, em centavos, que o seu servidor fixou; o comprador o vê e não pode mudá-lo. Nulo quando é o comprador quem digita o valor.
    # @return [Integer, nil]
    attr_reader :amount_cents

    # Endereço https para onde o comprador volta se desistir; vazio sem ele.
    # @return [String]
    attr_reader :cancel_url

    # O id do pedido no seu sistema, como o seu servidor o enviou; vazio sem ele. Volta no checkout, no pedido, no pagamento e nos eventos.
    # @return [String]
    attr_reader :client_reference_id

    # O segredo que o navegador do comprador usa para ler, atualizar e pagar a sessão, sem chave de API. Só esta resposta o traz; entregue-o à página que monta os campos seguros. Vem vazio na repetição de uma criação idempotente.
    # @return [String]
    attr_reader :client_secret

    # Quando a sessão e o client_secret deixam de valer.
    # @return [String]
    attr_reader :client_secret_expires_at

    # @return [String]
    attr_reader :created_at

    # O desconto que o checkout aplica sozinho, como o seu servidor o enviou na criação; vazio sem ele. O comprador o vê no resumo e ele conta desde a primeira cobrança.
    # @return [String]
    attr_reader :discount_id

    # Quando o link deixa de abrir sessões; nulo sem prazo.
    # @return [String, nil]
    attr_reader :expires_at

    # Quantos dias o seu servidor somou ao primeiro período da assinatura (first_period_extra_days na criação); nulo quando o primeiro período é o comum. O comprador paga hoje o valor cheio, e a próxima cobrança só acontece no fim do período mais longo.
    # @return [Integer, nil]
    attr_reader :first_period_extra_days

    # O ID do link do checkout, o que GET e PATCH /checkouts/{id} recebem.
    # @return [String]
    attr_reader :id

    # As linhas do valor fixado, na ordem em que foram enviadas; vazio sem elas.
    # @return [Array<CheckoutLine>]
    attr_reader :items

    # Como o lojista chama o checkout nas próprias telas; o comprador não vê.
    # @return [String]
    attr_reader :label

    # Os pares que o seu servidor enviou; voltam no pedido, no pagamento e nos eventos da venda (checkout.*, order.*, checkout_payment.* e refund.*).
    # @return [Hash{String => Object}]
    attr_reader :metadata

    # Falso quando o seu sistema avisa o comprador das cobranças de renovação e a Peráta fica quieta.
    # @return [Boolean]
    attr_reader :notify_customer_email

    # @return [String]
    attr_reader :price_id

    # @return [String]
    attr_reader :product_id

    # @return [Integer]
    attr_reader :quantity

    # O renewal_mode da criação: manual, automatic ou buyer_choice; vazio quando foi omitido. A assinatura que o pagamento começa traz o modo a que isso se resolveu em Subscription.renewal_mode.
    # @return [String ("manual", "automatic", "buyer_choice")]
    attr_reader :renewal_mode

    # O ID da sessão de checkout; as rotas de cliente dela são /checkouts/client/{client_secret}.
    # @return [String]
    attr_reader :session_id

    # O showcase a que pertence: o da chave de API que fez a chamada. Uma chave só alcança o seu showcase.
    # @return [String]
    attr_reader :showcase_id

    # active abre sessões de compra; archived saiu de circulação.
    # @return [String ("active", "archived")]
    attr_reader :status

    # Lê o estado da sessão depois que o client_secret é consumido: GET /checkouts/client/status/{status_key}. Só esta resposta o traz.
    # @return [String]
    attr_reader :status_key

    # O dia da primeira cobrança de uma assinatura que começa numa data (a meia-noite desse dia em São Paulo, com o fuso); nulo quando o checkout cobra na hora ou começa por um teste em dias. O cartão é guardado sem cobrança e a cobrança acontece nesse dia.
    # @return [String, nil]
    attr_reader :subscription_start_at

    # Endereço https para onde o comprador volta depois de pagar; vazio sem ele.
    # @return [String]
    attr_reader :success_url

    # O endereço hospedado desta sessão: redirecione o comprador para cá, ou abra-o no modal, e ele paga na página da Peráta exatamente a sessão que esta resposta abriu, que aparece no status_key, no GET da sessão e nos webhooks com o mesmo checkout_id. Quem abre o endereço depois do pagamento vê a confirmação e nada é cobrado de novo. Na repetição de uma criação idempotente o segredo não existe mais e o endereço volta a ser o do link, que abre uma sessão nova a cada visita.
    # @return [String]
    attr_reader :url

    def initialize(amount_cents:, cancel_url:, client_reference_id:, client_secret:, client_secret_expires_at:, created_at:, discount_id:, expires_at:, first_period_extra_days:, id:, items:, label:, metadata:, notify_customer_email:, price_id:, product_id:, quantity:, renewal_mode:, session_id:, showcase_id:, status:, status_key:, subscription_start_at:, success_url:, url:)
      @amount_cents = amount_cents
      @cancel_url = cancel_url
      @client_reference_id = client_reference_id
      @client_secret = client_secret
      @client_secret_expires_at = client_secret_expires_at
      @created_at = created_at
      @discount_id = discount_id
      @expires_at = expires_at
      @first_period_extra_days = first_period_extra_days
      @id = id
      @items = items
      @label = label
      @metadata = metadata
      @notify_customer_email = notify_customer_email
      @price_id = price_id
      @product_id = product_id
      @quantity = quantity
      @renewal_mode = renewal_mode
      @session_id = session_id
      @showcase_id = showcase_id
      @status = status
      @status_key = status_key
      @subscription_start_at = subscription_start_at
      @success_url = success_url
      @url = url
      freeze
    end

    # Builds a CheckoutCreated from the API's JSON.
    def self.from_hash(data)
      new(
        amount_cents: data["amount_cents"],
        cancel_url: data.fetch("cancel_url"),
        client_reference_id: data.fetch("client_reference_id"),
        client_secret: data.fetch("client_secret"),
        client_secret_expires_at: data.fetch("client_secret_expires_at"),
        created_at: data.fetch("created_at"),
        discount_id: data.fetch("discount_id"),
        expires_at: data["expires_at"],
        first_period_extra_days: data["first_period_extra_days"],
        id: data.fetch("id"),
        items: data.fetch("items").map { |item| CheckoutLine.from_hash(item) },
        label: data.fetch("label"),
        metadata: data.fetch("metadata"),
        notify_customer_email: data.fetch("notify_customer_email"),
        price_id: data.fetch("price_id"),
        product_id: data.fetch("product_id"),
        quantity: data.fetch("quantity"),
        renewal_mode: data.fetch("renewal_mode"),
        session_id: data.fetch("session_id"),
        showcase_id: data.fetch("showcase_id"),
        status: data.fetch("status"),
        status_key: data.fetch("status_key"),
        subscription_start_at: data["subscription_start_at"],
        success_url: data.fetch("success_url"),
        url: data.fetch("url")
      )
    end
