    # @return [String]
    attr_reader :id

    # Juros do parcelamento pagos pelo comprador, cobrados além de amount_cents.
    # @return [Integer]
    attr_reader :installment_interest_cents

    # Em quantas parcelas o cartão de crédito foi cobrado; 1 à vista.
