      @period_end = period_end
      @period_start = period_start
      @price_id = price_id
      @product_id = product_id
      @refunded_amount_cents = refunded_amount_cents
      @showcase_id = showcase_id
      @status = status
      @subscription_id = subscription_id
      @subtotal_cents = subtotal_cents
      freeze
    end

