      @created_at = created_at
      @id = id
      @metadata = metadata
      @order_id = order_id
      @payment_id = payment_id
      @reason = reason
      @refund_metadata = refund_metadata
      @showcase_id = showcase_id
      @status = status
      freeze
    end

    # Builds a Refund from the API's JSON.
    def self.from_hash(data)
      new(
        amount_cents: data.fetch("amount_cents"),
        client_reference_id: data.fetch("client_reference_id"),
        created_at: data.fetch("created_at"),
        id: data.fetch("id"),
        metadata: data.fetch("metadata"),
        order_id: data.fetch("order_id"),
        payment_id: data.fetch("payment_id"),
        reason: data.fetch("reason"),
        refund_metadata: data.fetch("refund_metadata"),
        showcase_id: data.fetch("showcase_id"),
        status: data.fetch("status")
      )
    end
  end

  # RenewalCharge is a resource of Peráta's API.
  class RenewalCharge < Model
    MEMBERS = %i[amount_cents client_reference_id currency customer_id cycle_sequence days_until_due due_at expires_at id label metadata notify_customer_email payment_url period_end period_start price_id product_id reminder renewal_mode showcase_id subscription_id].freeze

    # O que o comprador paga, em centavos: o ciclo já com desconto e rateio.
    # @return [Integer]
    attr_reader :amount_cents

    # O client_reference_id da assinatura.
    # @return [String]
    attr_reader :client_reference_id

    # @return [String ("BRL")]
    attr_reader :currency

    # @return [String]
    attr_reader :customer_id

    # O ciclo que a cobrança paga: 2 é a primeira renovação.
    # @return [Integer]
    attr_reader :cycle_sequence

    # Só nos lembretes: 3 em before_due, 0 em on_due; nulo no resto.
    # @return [Integer, nil]
    attr_reader :days_until_due

    # Até quando a cobrança deve ser paga sem a assinatura ficar em atraso: o fim do período que ela cobra. Passado o prazo, a assinatura vira past_due e o mesmo payment_url continua valendo por mais 72 horas de tolerância; depois disso a assinatura é suspensa.
    # @return [String]
    attr_reader :due_at

    # Quando o payment_url deixa de abrir; sempre depois da tolerância de 72 horas.
    # @return [String, nil]
    attr_reader :expires_at

    # O id da cobrança, que é o do ciclo da assinatura que ela cobra. O pedido só existe depois do pagamento: o order.paid que vem então traz o mesmo subscription_id e cycle_sequence.
    # @return [String]
    attr_reader :id

    # O label da assinatura; vazio sem ele.
    # @return [String]
    attr_reader :label

    # Os metadados da assinatura.
    # @return [Hash{String => Object}]
    attr_reader :metadata

    # Se a Peráta escreve ao comprador desta cobrança.
    # @return [Boolean]
    attr_reader :notify_customer_email

    # A página da Peráta onde o comprador paga esta cobrança, por cartão, Pix ou boleto. O Pix é gerado nessa página, quando o comprador o escolhe, e vale 24 horas: a Peráta não gera o Pix na abertura da cobrança porque ele venceria antes do prazo da cobrança e, enquanto vale, impediria pagar de outro jeito. Entregue este endereço ao comprador.
    # @return [String]
    attr_reader :payment_url

    # @return [String]
    attr_reader :period_end

    # @return [String]
    attr_reader :period_start

    # @return [String]
    attr_reader :price_id

    # @return [String]
    attr_reader :product_id

    # Só nos eventos subscription.renewal_reminder: before_due (3 dias antes de due_at) ou on_due (no vencimento). Nulo na cobrança e em subscription.renewal_due.
    # @return [String ("before_due", "on_due", "null"), nil]
    attr_reader :reminder

    # O modo de renovação da assinatura. Uma cobrança em aberto existe nos modos manual e, quando o cartão é recusado, card.
    # @return [String ("manual", "card", "pix_automatic")]
    attr_reader :renewal_mode

    # O showcase a que pertence: o da chave de API que fez a chamada.
    # @return [String]
    attr_reader :showcase_id

    # @return [String]
    attr_reader :subscription_id

    def initialize(amount_cents:, client_reference_id:, currency:, customer_id:, cycle_sequence:, days_until_due:, due_at:, expires_at:, id:, label:, metadata:, notify_customer_email:, payment_url:, period_end:, period_start:, price_id:, product_id:, reminder:, renewal_mode:, showcase_id:, subscription_id:)
      @amount_cents = amount_cents
      @client_reference_id = client_reference_id
      @currency = currency
      @customer_id = customer_id
      @cycle_sequence = cycle_sequence
      @days_until_due = days_until_due
      @due_at = due_at
      @expires_at = expires_at
      @id = id
      @label = label
      @metadata = metadata
      @notify_customer_email = notify_customer_email
      @payment_url = payment_url
      @period_end = period_end
      @period_start = period_start
      @price_id = price_id
      @product_id = product_id
      @reminder = reminder
      @renewal_mode = renewal_mode
      @showcase_id = showcase_id
      @subscription_id = subscription_id
      freeze
    end

    # Builds a RenewalCharge from the API's JSON.
    def self.from_hash(data)
      new(
        amount_cents: data.fetch("amount_cents"),
        client_reference_id: data.fetch("client_reference_id"),
