  # A assinatura como a API a devolve (Subscription) e, nos eventos que uma cobrança recusada causou (subscription.past_due, subscription.suspended e o subscription.updated que os acompanha), a cobrança recusada em payment_failure.
  class WebhookSubscription < Model
    MEMBERS = %i[amount_cents cancel_at_period_end client_reference_id currency current_period_end current_period_start customer_id discount_ends_at discount_id first_period_extra_days id interval label metadata notify_customer_email payment_failure pending_update price_id product_id quantity renewal_mode showcase_id status suspended_at suspension_reason trial_end trial_start].freeze

    # O que a assinatura cobra a cada ciclo, em centavos, já para a quantity que ela tem: é o total do ciclo, não o preço de uma unidade. O preço por unidade, por assento ou por faixas já está aplicado à quantity.
    # @return [Integer]
    attr_reader :amount_cents

    # @return [Boolean]
    attr_reader :cancel_at_period_end

    # O id do pedido no seu sistema, enviado ao criar o checkout que vendeu a assinatura; vazio sem ele. Cada pedido de renovação traz o mesmo client_reference_id, e o mesmo metadata, para você achar o cliente.
    # @return [String]
    attr_reader :client_reference_id

    # @return [String ("BRL")]
    attr_reader :currency

    # @return [String]
    attr_reader :current_period_end

    # @return [String]
    attr_reader :current_period_start

    # @return [String]
    attr_reader :customer_id

    # Quando o desconto deixa de valer: o fim do último ciclo que ele ainda abate (num desconto de uma vez, o fim do primeiro ciclo pago). Nulo quando não há desconto e quando ele vale para sempre.
    # @return [String, nil]
    attr_reader :discount_ends_at

    # O desconto em vigor na assinatura, que se aplica aos próximos ciclos até acabar; nulo sem desconto e depois que ele acabou.
    # @return [String, nil]
    attr_reader :discount_id

    # Quantos dias o checkout que vendeu a assinatura somou ao primeiro período, para você conferir; nulo quando o primeiro período foi o comum. O primeiro período vai do dia do pagamento até esse dia mais um intervalo do preço mais estes dias, e current_period_end já vem com eles.
    # @return [Integer, nil]
    attr_reader :first_period_extra_days

    # @return [String]
    attr_reader :id

    # @return [String]
    attr_reader :interval

    # O nome que o lojista deu à assinatura, copiado do label do checkout que a vendeu; vazio sem ele.
    # @return [String]
    attr_reader :label

    # Metadados do lojista: pares chave e valor (texto, número ou booleano); objeto vazio quando não há.
    # @return [Hash{String => Object}]
    attr_reader :metadata

    # Verdadeiro enquanto a Peráta escreve ao comprador a cada cobrança de renovação.
    # @return [Boolean]
    attr_reader :notify_customer_email

    # A cobrança recusada que causou o evento; só nos eventos de cobrança recusada.
    # @return [WebhookSubscriptionPaymentFailure, nil]
    attr_reader :payment_failure

    # A mudança de plano ou de quantidade agendada para o próximo período (PATCH com proration_behavior next_period); nulo quando não há nenhuma. Até effective_at a assinatura segue com o price_id, a quantity e o amount_cents de cima.
    # @return [WebhookSubscriptionPendingUpdate, nil]
    attr_reader :pending_update

    # @return [String]
    attr_reader :price_id

    # @return [String]
    attr_reader :product_id

    # Quantas unidades ou assentos a assinatura cobre, de 1 em diante; 1 num preço sem quantidade. amount_cents é o total do ciclo para esta quantity.
    # @return [Integer]
    attr_reader :quantity

    # Como os próximos períodos são cobrados: manual (uma cobrança para o comprador pagar a cada ciclo, com o evento subscription.renewal_due; o cartão nunca é cobrado), card (o cartão de crédito guardado, cobrado sozinho) ou pix_automatic (o banco debita cada cobrança). card e pix_automatic são os automáticos.
    # @return [String ("manual", "card", "pix_automatic")]
    attr_reader :renewal_mode

    # O showcase da venda.
    # @return [String]
    attr_reader :showcase_id

    # @return [String ("trialing", "active", "past_due", "suspended", "paused", "canceled")]
    attr_reader :status

    # Quando a assinatura foi suspensa; nulo enquanto não está suspensa.
    # @return [String, nil]
    attr_reader :suspended_at

    # Por que foi suspensa; nulo enquanto não está suspensa.
    # @return [String ("retries_exhausted", "declined_not_retryable", "dispute"), nil]
    attr_reader :suspension_reason

    # @return [String, nil]
    attr_reader :trial_end

    # @return [String, nil]
    attr_reader :trial_start

    def initialize(amount_cents:, cancel_at_period_end:, client_reference_id:, currency:, current_period_end:, current_period_start:, customer_id:, discount_ends_at:, discount_id:, first_period_extra_days:, id:, interval:, label:, metadata:, notify_customer_email:, payment_failure: nil, pending_update:, price_id:, product_id:, quantity:, renewal_mode:, showcase_id:, status:, suspended_at:, suspension_reason:, trial_end:, trial_start:)
      @amount_cents = amount_cents
      @cancel_at_period_end = cancel_at_period_end
      @client_reference_id = client_reference_id
      @currency = currency
      @current_period_end = current_period_end
      @current_period_start = current_period_start
      @customer_id = customer_id
      @discount_ends_at = discount_ends_at
      @discount_id = discount_id
      @first_period_extra_days = first_period_extra_days
      @id = id
      @interval = interval
      @label = label
      @metadata = metadata
      @notify_customer_email = notify_customer_email
      @payment_failure = payment_failure
      @pending_update = pending_update
      @price_id = price_id
      @product_id = product_id
      @quantity = quantity
      @renewal_mode = renewal_mode
      @showcase_id = showcase_id
      @status = status
      @suspended_at = suspended_at
      @suspension_reason = suspension_reason
      @trial_end = trial_end
      @trial_start = trial_start
      freeze
    end

    # Builds a WebhookSubscription from the API's JSON.
    def self.from_hash(data)
      new(
        amount_cents: data.fetch("amount_cents"),
        cancel_at_period_end: data.fetch("cancel_at_period_end"),
        client_reference_id: data.fetch("client_reference_id"),
        currency: data.fetch("currency"),
        current_period_end: data.fetch("current_period_end"),
        current_period_start: data.fetch("current_period_start"),
        customer_id: data.fetch("customer_id"),
        discount_ends_at: data["discount_ends_at"],
        discount_id: data["discount_id"],
        first_period_extra_days: data["first_period_extra_days"],
        id: data.fetch("id"),
        interval: data.fetch("interval"),
        label: data.fetch("label"),
        metadata: data.fetch("metadata"),
        notify_customer_email: data.fetch("notify_customer_email"),
        payment_failure: data["payment_failure"]&.then { |value| WebhookSubscriptionPaymentFailure.from_hash(value) },
        pending_update: data["pending_update"]&.then { |value| WebhookSubscriptionPendingUpdate.from_hash(value) },
        price_id: data.fetch("price_id"),
        product_id: data.fetch("product_id"),
        quantity: data.fetch("quantity"),
        renewal_mode: data.fetch("renewal_mode"),
        showcase_id: data.fetch("showcase_id"),
        status: data.fetch("status"),
        suspended_at: data["suspended_at"],
        suspension_reason: data["suspension_reason"],
        trial_end: data["trial_end"],
        trial_start: data["trial_start"]
      )
    end
  end

